R_API int r_utf_block_idx(RRune ch) { /* <=== r_utf_block_idx */ 
	const int last = r_utf_blocks_count;
	int low, hi, mid;

	low = 0;
	hi = last - 1;

	do {
		mid = (low + hi) >> 1;
		if (ch >= r_utf_blocks[mid].from && ch <= r_utf_blocks[mid].to) {
			return mid;
		}
		if (mid < last && ch > r_utf_blocks[mid].to) {
			low = mid + 1;
		}
		if (mid < last && ch < r_utf_blocks[mid].from) {
			hi = mid - 1;
		}
	} while (low <= hi);

	return r_utf_blocks_count - 1; /* index for "No_Block" */
}

R_API size_t r_str_nlen(const char *str, int n) { /* <=== r_str_nlen */ 
	size_t len = 0;
	if (str) {
		while (n > 0 && *str) {
			len++;
			str++;
			n--;
		}
	}
	return len;
}

