R_API size_t r_str_ncpy(char *dst, const char *src, size_t n) { /* <=== r_str_ncpy */ 
	size_t i;

	// do not do anything if n is 0
	if (n == 0) {
		return 0;
	}

	n--;
	for (i = 0; src[i] && n > 0; i++, n--) {
		dst[i] = src[i];
	}
	dst[i] = 0;
	return i;
}

