}

R_API int r_utf32_decode(const ut8 *ptr, int ptrlen, RRune *ch, bool bigendian) { /* <=== r_utf32_decode */ 
	if (ptrlen < 1) {
		return 0;
	}
	int low = 0;
	int high = 3;
	if (bigendian) {
		low = 3;
		high = 0;
	}
	if (ptrlen > 3) {
		int sign = bigendian ? -1 : 1;
		if (ch) {
			int i;
			*ch = (ut32)ptr[low];
			for (i = 1; i < 4; i++) {
				*ch |= (ut32)ptr[3 - high + i * sign] << 8 * i;
			}
		}
		if (ptr[high] || ptr[high - 1 * sign]) {
			return 4;
		}
		if (ptr[low + 1 * sign]) {
			return 2;
		}
		return 1;
	}
	return 0;
}

R_API int r_utf8_encode(ut8 *ptr, const RRune ch) { /* <=== r_utf8_encode */ 
	if (ch < 0x80) {
		ptr[0] = (ut8)ch;
		return 1;
	}
	else if (ch < 0x800) {
		ptr[0] = 0xc0 | (ch >> 6);
		ptr[1] = 0x80 | (ch & 0x3f);
		return 2;
	}
	else if (ch < 0x10000) {
		ptr[0] = 0xe0 | (ch >> 12);
		ptr[1] = 0x80 | ((ch >> 6) & 0x3f);
		ptr[2] = 0x80 | (ch & 0x3f);
		return 3;
	}
	else if (ch < 0x200000) {
		ptr[0] = 0xf0 | (ch >> 18);
		ptr[1] = 0x80 | ((ch >> 12) & 0x3f);
		ptr[2] = 0x80 | ((ch >> 6) & 0x3f);
		ptr[3] = 0x80 | (ch & 0x3f );
		return 4;
	}
	return 0;
}

static void print_string(RBinFile *bf, RBinString *string, int raw, PJ *pj) { /* <=== print_string */ 
	r_return_if_fail (bf && string);

	int mode = bf->strmode;
	RBin *bin = bf->rbin;
	if (!bin) {
		return;
	}
	RIO *io = bin->iob.io;
	if (!io) {
		return;
	}
	RBinSection *s = r_bin_get_section_at (bf->o, string->paddr, false);
	if (s) {
		string->vaddr = s->vaddr + (string->paddr - s->paddr);
	}
	const char *section_name = s ? s->name : "";
	const char *type_string = r_bin_string_type (string->type);
	ut64 vaddr = r_bin_get_vaddr (bin, string->paddr, string->vaddr);
	ut64 addr = vaddr;

	// If raw string dump mode, use printf to dump directly to stdout.
	//  PrintfCallback temp = io->cb_printf;
	switch (mode) {
	case R_MODE_JSON:
		{
			if (pj) {
				pj_o (pj);
				pj_kn (pj, "vaddr", vaddr);
				pj_kn (pj, "paddr", string->paddr);
				pj_kn (pj, "ordinal", string->ordinal);
				pj_kn (pj, "size", string->size);
				pj_kn (pj, "length", string->length);
				pj_ks (pj, "section", section_name);
				pj_ks (pj, "type", type_string);
				pj_ks (pj, "string", string->string);
				pj_end (pj);
			}
		}
		break;
	case R_MODE_SIMPLEST:
		io->cb_printf ("%s\n", string->string);
		break;
	case R_MODE_SIMPLE:
		if (raw == 2) {
			io->cb_printf ("0x%08"PFMT64x" %s\n", addr, string->string);
		} else {
			io->cb_printf ("%s\n", string->string);
		}
		break;
	case R_MODE_RADARE: {
		char *f_name = strdup (string->string);
		r_name_filter (f_name, -1);
		if (bin->prefix) {
			io->cb_printf ("f %s.str.%s %u @ 0x%08"PFMT64x"\n"
					"Cs %u @ 0x%08"PFMT64x"\n",
					bin->prefix, f_name, string->size, addr,
					string->size, addr);
		} else {
			io->cb_printf ("f str.%s %u @ 0x%08"PFMT64x"\n"
					"Cs %u @ 0x%08"PFMT64x"\n",
					f_name, string->size, addr,
					string->size, addr);
		}
		free (f_name);
		break;
		}
	case R_MODE_PRINT:
		io->cb_printf ("%03u 0x%08" PFMT64x " 0x%08" PFMT64x " %3u %3u "
			       "(%s) %5s %s\n",
			string->ordinal, string->paddr, vaddr,
			string->length, string->size,
			section_name, type_string, string->string);
		break;
	}
}

R_API char *r_str_ndup(const char *ptr, int len) { /* <=== r_str_ndup */ 
	if (!ptr || len < 0) {
		return NULL;
	}
	size_t plen = r_str_nlen (ptr, len);
	size_t olen = R_MIN (len, plen);
	char *out = malloc (olen + 1);
	if (!out) {
		return NULL;
	}
	memcpy (out, ptr, olen);
	out[olen] = 0;
	return out;
}

R_API int *r_utf_block_list(const ut8 *str, int len, int **freq_list) { /* <=== r_utf_block_list */ 
	if (!str) {
		return NULL;
	}
	if (len < 0) {
		len = strlen ((const char *)str);
	}
	static R_TH_LOCAL int block_freq[r_utf_blocks_count] = {0};
	int *list = R_NEWS (int, len + 1);
	if (!list) {
		return NULL;
	}
	int *freq_list_ptr = NULL;
	if (freq_list) {
		*freq_list = R_NEWS (int, len + 1);
		if (!*freq_list) {
			free (list);
			return NULL;
		}
		freq_list_ptr = *freq_list;
	}
	int *list_ptr = list;
	const ut8 *str_ptr = str;
	const ut8 *str_end = str + len;
	RRune ch;
